/* Replay Python's own recorded verdicts through the browser's copy of the
 * arithmetic.
 *
 * This test is the only thing preventing a silent divergence between
 * `phoneloop/metrics.py` and `src/lib/knobs.ts`. Both sides can be internally
 * consistent, fully covered by their own tests, and still disagree — and the
 * symptom would be a confident PASS on screen for a row the pipeline calls a
 * FAIL, with no red anywhere.
 *
 * The fixture is generated by `python scripts/export_knob_golden.py` and
 * committed. If it changes, Python changed; mirror it here or explain why not.
 */

import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import {
  EVERYTHING_ELSE_BP,
  bp,
  check,
  fvfBp,
  formatG,
  maxCost,
  perOrderPence,
  type Knobs,
  type MetricsInput,
} from "../src/lib/knobs";

interface Case {
  id: string;
  source: string;
  leaf_category_id: string | null;
  fvf_bp: number;
  competitors: number | null;
  metrics: MetricsInput;
}

interface Expectation {
  case: string;
  setting: string;
  max_cost_at_floor_pence: number | null;
  max_cost_at_median_pence: number | null;
  knobs: {
    knob: string;
    value: unknown;
    threshold: unknown;
    passed: boolean | null;
    denominator: number;
    coverage: number;
    note: string;
  }[];
}

interface Golden {
  schema_version: number;
  n_cases: number;
  n_expectations: number;
  check_input_fields: string[];
  fee_constants: Record<string, number>;
  inert_settings: string[];
  cases: Case[];
  knob_settings: { label: string; knobs: Knobs }[];
  expected: Expectation[];
}

const golden: Golden = JSON.parse(
  readFileSync(fileURLToPath(new URL("./fixtures/knob-golden.json", import.meta.url)), "utf-8"),
);

/* At runtime the leaf→rate map comes from `fees.json`, which Python resolves
 * for every leaf in the store. Building it from the fixture's own cases is
 * the same shape; the fallback for a leaf that is NOT in the map is asserted
 * separately below, because a map built from the cases can never exercise it. */
const fvfByLeaf: Record<string, number> = {};
for (const c of golden.cases) {
  if (c.leaf_category_id) fvfByLeaf[c.leaf_category_id] = c.fvf_bp;
}

const settings = new Map(golden.knob_settings.map((s) => [s.label, s.knobs]));
const cases = new Map(golden.cases.map((c) => [c.id, c]));

describe("the fixture itself", () => {
  it("is the schema this file was written against", () => {
    expect(golden.schema_version).toBe(1);
  });

  it("pins something", () => {
    expect(golden.n_expectations).toBeGreaterThan(500);
    expect(golden.expected).toHaveLength(golden.n_expectations);
  });

  it("has no knob setting that changes nothing", () => {
    // An inert setting pins no verdict, so a whole knob could be unimplemented
    // here and every assertion below would still pass.
    expect(golden.inert_settings).toEqual([]);
  });

  it("declares the same input surface this port accepts", () => {
    const accepted: (keyof MetricsInput)[] = [
      "n_listings",
      "price_median_pence",
      "price_median_denominator",
      "price_floor_pence",
      "price_floor_denominator",
      "str_window_bp",
      "str_window_denominator",
      "str_window_days",
      "str_lifetime",
      "str_lifetime_denominator",
      "eta_median_days",
      "eta_median_denominator",
      "feedback_median_bp",
      "feedback_median_n",
      "feedback_median_denominator",
    ];
    // If Python starts reading a 16th field, this fails here rather than
    // silently leaving that field unread in the browser.
    expect([...golden.check_input_fields].sort()).toEqual([...accepted].sort());
  });

  it("agrees with the fee constants compiled into this file", () => {
    expect(golden.fee_constants.everything_else_bp).toBe(EVERYTHING_ELSE_BP);
  });
});

describe("max_cost matches Python on every case × knob setting", () => {
  for (const row of golden.expected) {
    const c = cases.get(row.case)!;
    const knobs = settings.get(row.setting)!;
    it(`${row.case} under ${row.setting}`, () => {
      const floor =
        c.metrics.price_floor_pence !== null
          ? maxCost(c.metrics.price_floor_pence, c.leaf_category_id, knobs, fvfByLeaf)
          : null;
      const median =
        c.metrics.price_median_pence !== null
          ? maxCost(c.metrics.price_median_pence, c.leaf_category_id, knobs, fvfByLeaf)
          : null;
      expect(floor).toBe(row.max_cost_at_floor_pence);
      expect(median).toBe(row.max_cost_at_median_pence);
    });
  }
});

describe("check() matches Python on every case × knob setting", () => {
  for (const row of golden.expected) {
    const c = cases.get(row.case)!;
    const knobs = settings.get(row.setting)!;
    it(`${row.case} under ${row.setting}`, () => {
      const got = check(c.metrics, knobs, {
        competitors: c.competitors,
        maxCostAtFloorPence: row.max_cost_at_floor_pence,
        maxCostAtMedianPence: row.max_cost_at_median_pence,
      });

      expect(got).toHaveLength(row.knobs.length);
      got.forEach((actual, i) => {
        const want = row.knobs[i]!;
        expect(actual.knob).toBe(want.knob);
        expect(actual.value).toEqual(want.value);
        expect(actual.threshold).toEqual(want.threshold);
        // toBe, not toEqual: `null` and `false` are both falsy and this is the
        // one comparison where confusing them changes the ranking.
        expect(actual.passed).toBe(want.passed);
        expect(actual.denominator).toBe(want.denominator);
        expect(actual.coverage).toBeCloseTo(want.coverage, 9);
        expect(actual.note).toBe(want.note);
      });
    });
  }
});

describe("the paths a fixture built from real leaves cannot reach", () => {
  it("falls to the everything-else rate for a leaf the table does not know", () => {
    expect(fvfBp("not-a-leaf", fvfByLeaf)).toBe(EVERYTHING_ELSE_BP);
  });

  it("falls to the everything-else rate for no leaf at all", () => {
    expect(fvfBp(null, fvfByLeaf)).toBe(EVERYTHING_ELSE_BP);
    expect(fvfBp("", fvfByLeaf)).toBe(EVERYTHING_ELSE_BP);
  });

  it("rounds half UP, the way Python's floor-division trick does", () => {
    // 1 x 5000bp is exactly 0.5 and must go to 1, not to 0.
    expect(bp(1, 5000)).toBe(1);
    expect(bp(3, 5000)).toBe(2); // 1.5 -> 2
    expect(bp(0, 1290)).toBe(0);
    // Banker's rounding would give 0 and 2 here. Math.round would agree with
    // Python on these, but not on the negative operands it must never see.
  });

  it("switches the per-order fee exactly at GBP 10, inclusive", () => {
    expect(perOrderPence(1000)).toBe(30);
    expect(perOrderPence(1001)).toBe(40);
  });
});

describe("formatG reproduces Python's %g", () => {
  // These strings are interpolated into note text the golden compares
  // character for character, so a formatting difference is a test failure
  // upstream — but pinning it directly says WHY when it breaks.
  it.each([
    [30.0, "30"],
    [1.0, "1"],
    [1.5, "1.5"],
    [1.18729, "1.18729"],
    [1.19444, "1.19444"],
    [0.5, "0.5"],
    [24.0, "24"],
    [null, "?"],
  ])("%s -> %s", (input, want) => {
    expect(formatG(input as number | null)).toBe(want);
  });
});
